item.description:
 &lt;h1 id=&#34;Open-ERP-System-open-erp&#34;&gt;&lt;a href=&#34;#Open-ERP-System-open-erp&#34; class=&#34;headerlink&#34; title=&#34;Open ERP System (open-erp)&#34;&gt;&lt;/a&gt;Open ERP System (open-erp)&lt;/h1&gt;&lt;p&gt;A full-stack ERP system based on webman v2 + Flutter.&lt;/p&gt;
&lt;h2 id=&#34;Feature-List&#34;&gt;&lt;a href=&#34;#Feature-List&#34; class=&#34;headerlink&#34; title=&#34;Feature List&#34;&gt;&lt;/a&gt;Feature List&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Business Domain&lt;/th&gt;
&lt;th&gt;Feature&lt;/th&gt;
&lt;th&gt;Notes&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;🔐 Authentication&lt;/td&gt;
&lt;td&gt;Login/register/token refresh/logout&lt;/td&gt;
&lt;td&gt;Click captcha + JWT + blacklist&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;Account lockout&lt;/td&gt;
&lt;td&gt;Locked for 15 minutes after 5 failures&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;Concurrent session limit&lt;/td&gt;
&lt;td&gt;Max 3 valid tokens per user&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📊 Dashboard&lt;/td&gt;
&lt;td&gt;Business overview/sales board/inventory board/finance board&lt;/td&gt;
&lt;td&gt;Redis cache for 5 minutes&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;👥 User management&lt;/td&gt;
&lt;td&gt;CRUD + batch delete/enable/disable&lt;/td&gt;
&lt;td&gt;Soft delete + password re-confirmation&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;Excel bulk import&lt;/td&gt;
&lt;td&gt;Row-by-row validation + error report&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🔒 Roles and permissions&lt;/td&gt;
&lt;td&gt;Role CRUD + permission tree&lt;/td&gt;
&lt;td&gt;RBAC with method.path granular authorization&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;⚙ System config&lt;/td&gt;
&lt;td&gt;Key-value CRUD&lt;/td&gt;
&lt;td&gt;Grouped management&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📋 Operation audit&lt;/td&gt;
&lt;td&gt;Log query + source client detection&lt;/td&gt;
&lt;td&gt;Automatic detection of 8 platforms&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📁 File management&lt;/td&gt;
&lt;td&gt;Upload/Excel export/PDF export&lt;/td&gt;
&lt;td&gt;Automatic masking of sensitive data&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🛡 Security protection&lt;/td&gt;
&lt;td&gt;18 layers of defense in depth&lt;/td&gt;
&lt;td&gt;XSS/SQL injection/path traversal/command injection/CSRF/rate limiting/CSP…&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🏥 Operations&lt;/td&gt;
&lt;td&gt;Health check/metrics/API docs/security.txt&lt;/td&gt;
&lt;td&gt;Prometheus + OpenAPI 3.0&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📦 Product management&lt;/td&gt;
&lt;td&gt;Product records/SKU/multi-spec/multi-unit/category/brand/price strategy&lt;/td&gt;
&lt;td&gt;Multi-level category tree + multi-unit conversion&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;Warehouse locations&lt;/td&gt;
&lt;td&gt;Multi-warehouse, multi-location management&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;/td&gt;
&lt;td&gt;Supplier/customer records&lt;/td&gt;
&lt;td&gt;Contacts/bank accounts/credit limit&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📥 Purchasing&lt;/td&gt;
&lt;td&gt;Requisition → order → receipt → return → settlement&lt;/td&gt;
&lt;td&gt;Complete purchasing flow + approval&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📤 Sales&lt;/td&gt;
&lt;td&gt;Quotation → order → delivery → return → settlement&lt;/td&gt;
&lt;td&gt;Quotation-to-order + sales gross margin&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🏗 Inventory&lt;/td&gt;
&lt;td&gt;Real-time stock/batches/serial numbers/transfers/stocktakes/alerts&lt;/td&gt;
&lt;td&gt;Moving weighted average costing&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;💰 Finance&lt;/td&gt;
&lt;td&gt;AR/AP/receipts and payments/day journal/expense reimbursement/income statement/fixed assets/tax/multi-currency/budget/cost and profit centers&lt;/td&gt;
&lt;td&gt;Auto-generated AR/AP + write-off + comprehensive financial management&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🤝 CRM&lt;/td&gt;
&lt;td&gt;Customers/contacts/follow-up records/campaigns/service tickets/analytics reports/sales funnel/public pool/quotations/contracts&lt;/td&gt;
&lt;td&gt;Full customer lifecycle management&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;✅ Approval workflow&lt;/td&gt;
&lt;td&gt;Workflow definition/submit for approval/approve/reject/withdraw/my approvals&lt;/td&gt;
&lt;td&gt;Multi-node approval process engine&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🔔 Notifications&lt;/td&gt;
&lt;td&gt;Notification list/read marking/unread count/mark all as read&lt;/td&gt;
&lt;td&gt;Real-time message push with status tracking&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📐 Project management&lt;/td&gt;
&lt;td&gt;Projects/tasks/timesheets&lt;/td&gt;
&lt;td&gt;Project progress tracking and resource management&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;👤 HR&lt;/td&gt;
&lt;td&gt;Departments/employees/positions/attendance/leave/payroll&lt;/td&gt;
&lt;td&gt;Comprehensive HR management&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;🏭 Manufacturing&lt;/td&gt;
&lt;td&gt;BOM/production orders/routings/workstations/MRP&lt;/td&gt;
&lt;td&gt;Material requirements planning and production execution&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;📈 Custom reports&lt;/td&gt;
&lt;td&gt;Report templates/datasets/fields/filters/execution/scheduled jobs&lt;/td&gt;
&lt;td&gt;Visual report builder&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h4 id=&#34;Download&#34;&gt;&lt;a href=&#34;#Download&#34; class=&#34;headerlink&#34; title=&#34;Download&#34;&gt;&lt;/a&gt;&lt;a href=&#34;https://github.com/erikwang2013/erp-php-lite&#34;&gt;Download&lt;/a&gt;&lt;/h4&gt;&lt;h2 id=&#34;ERP-Modules&#34;&gt;&lt;a href=&#34;#ERP-Modules&#34; class=&#34;headerlink&#34; title=&#34;ERP Modules&#34;&gt;&lt;/a&gt;ERP Modules&lt;/h2&gt;&lt;p&gt;Data flow between the business modules:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Purchase receipt → automatic stock-in (moving weighted average costing) → automatic AP generation&lt;/li&gt;
&lt;li&gt;Sales delivery → automatic stock-out → automatic AR generation&lt;/li&gt;
&lt;li&gt;Receipts and payments → write off AR/AP → update the day journal&lt;/li&gt;
&lt;li&gt;Voucher review → automatically updates the general ledger (account summary) + subsidiary ledger (entry-by-entry records)&lt;/li&gt;
&lt;li&gt;Balance sheet → generated by automatically aggregating general ledger closing balances&lt;/li&gt;
&lt;li&gt;Cash flow statement → generated by automatically aggregating cash and bank day journals (operating/investing/financing classification)&lt;/li&gt;
&lt;li&gt;Approval workflow → business documents submitted for approval → multi-node routing → approval result calls back into the business module&lt;/li&gt;
&lt;li&gt;Notifications → triggered by approvals/alerts/system events → real-time push → user marks as read&lt;/li&gt;
&lt;li&gt;MRP → based on sales orders + BOM → calculates material requirements → generates purchase suggestions/production suggestions&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;Tech-Stack&#34;&gt;&lt;a href=&#34;#Tech-Stack&#34; class=&#34;headerlink&#34; title=&#34;Tech Stack&#34;&gt;&lt;/a&gt;Tech Stack&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Layer&lt;/th&gt;
&lt;th&gt;Technology&lt;/th&gt;
&lt;th&gt;Notes&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Backend framework&lt;/td&gt;
&lt;td&gt;webman v2 (workerman)&lt;/td&gt;
&lt;td&gt;Ultra-high-performance resident-process PHP framework&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;PHP version&lt;/td&gt;
&lt;td&gt;8.3+&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Database&lt;/td&gt;
&lt;td&gt;MySQL 8.0+&lt;/td&gt;
&lt;td&gt;Table prefix &lt;code&gt;erik_&lt;/code&gt;, BIGINT non-auto-increment primary keys&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Search engine&lt;/td&gt;
&lt;td&gt;Elasticsearch&lt;/td&gt;
&lt;td&gt;Sync and query through &lt;code&gt;webman-scout&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Admin frontend&lt;/td&gt;
&lt;td&gt;Flutter 3.x&lt;/td&gt;
&lt;td&gt;The web build uses a PC admin backend style (&lt;code&gt;apps/flutter/&lt;/code&gt;)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Mobile&lt;/td&gt;
&lt;td&gt;HarmonyOS ArkTS&lt;/td&gt;
&lt;td&gt;Native HarmonyOS client (&lt;code&gt;apps/harmonyos/&lt;/code&gt;), supports phone/tablet/2in1&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;Core-Dependencies&#34;&gt;&lt;a href=&#34;#Core-Dependencies&#34; class=&#34;headerlink&#34; title=&#34;Core Dependencies&#34;&gt;&lt;/a&gt;Core Dependencies&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Package&lt;/th&gt;
&lt;th&gt;Purpose&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/snowflake-php&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Snowflake algorithm to generate globally unique BIGINT primary keys&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/hashids&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Encrypt/decrypt IDs at the API layer to hide real database IDs&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/jwt-webman&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;JWT auth token issuance and verification&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/encryption&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Encrypt/decrypt sensitive data at the API transport layer&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/encryptable&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Automatic encrypt/decrypt of sensitive fields at the database storage layer&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/webman-scout&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Elasticsearch data sync and full-text search&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/season&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Country flag data&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/poster-php&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Click captcha generation and verification + poster generation&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/security-php&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Security tool checks&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;phpoffice/phpspreadsheet&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Excel export&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;barryvdh/laravel-dompdf&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;PDF export (based on Dompdf)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;hg/apidoc&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Automatic API documentation generation&lt;/td&gt;
&lt;td&gt;Annotation-based API docs, grouped by admin/client&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;Internationalization&#34;&gt;&lt;a href=&#34;#Internationalization&#34; class=&#34;headerlink&#34; title=&#34;Internationalization&#34;&gt;&lt;/a&gt;Internationalization&lt;/h2&gt;&lt;p&gt;Internationalization | Automatic Accept-Language header detection | Chinese/English bilingual support&lt;/p&gt;
&lt;h2 id=&#34;Project-Structure&#34;&gt;&lt;a href=&#34;#Project-Structure&#34; class=&#34;headerlink&#34; title=&#34;Project Structure&#34;&gt;&lt;/a&gt;Project Structure&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;40&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;41&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;42&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;open-erp/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── app/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── admin/controller/       # System management controllers (14)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── api/v1/controller/      # Client API (version controlled by the API-Version request header)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── controller/             # Business module controllers (70)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── product/            # Product/category/brand/warehouse/location/supplier/customer (7)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── purchase/           # Purchase requisition/order/receipt/return/settlement (5)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── sales/              # Sales quotation/order/delivery/return/settlement (5)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── inventory/          # Inventory/transactions/transfer/stocktake/alert (5)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── finance/            # AR-AP/voucher/receipt/payment/day journal/general ledger/subsidiary ledger/reports/assets/tax/multi-currency/budget/cost and profit centers (20)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── crm/                # Opportunities/follow-ups/funnel/contacts/public pool/contracts/quotations/campaigns/tickets/analytics (10)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── workflow/           # Workflow definition/approval submission/approve/reject/withdraw (2)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── notification/       # Notification list/read/unread count (1)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── project/            # Projects/tasks/timesheets (3)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── hr/                 # Departments/employees/positions/attendance/leave/payroll (5)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── manufacturing/      # BOM/production orders/routings/workstations/MRP (5)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── report/             # Report templates/datasets/execution/scheduled jobs (2)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── service/                # Business logic layer&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── inventory/          # Stock in/out + moving weighted average costing&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── finance/            # Automatic AR/AP generation + write-off&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── notification/       # Notification delivery service&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── model/                  # 121 Eloquent models (shared across modules)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── middleware/             # 9 middleware&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── common/                 # Hashids/Snowflake/Encryption services&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── queue/                  # Queue jobs&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── apps/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── flutter/                # Flutter cross-platform (Web PC + iOS/Android/macOS/Windows/Linux)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── harmonyos/              # Native HarmonyOS client&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── config/                     # Configuration files (with Chinese comments)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── plugin/hg/apidoc/        # API documentation config&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── database/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── migrations/             # SQL migration files (18, 122 tables)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── backup/                 # Backup/restore scripts&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── docs/                       # Architecture, design, security and API docs&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── tests/                      # PHPUnit tests (11 test files, 90 test methods, 168 assertions)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── resource/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── translations/           # Translation files (zh_CN, en)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│       ├── zh_CN/              # Chinese translations (127 keys)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│       └── en/                 # English translations (127 keys)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── public/                     # Public entry point&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── runtime/                    # Runtime files&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── vendor/                     # Composer dependencies&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;Requirements&#34;&gt;&lt;a href=&#34;#Requirements&#34; class=&#34;headerlink&#34; title=&#34;Requirements&#34;&gt;&lt;/a&gt;Requirements&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;PHP &amp;gt;= 8.3&lt;/li&gt;
&lt;li&gt;Composer 2.x&lt;/li&gt;
&lt;li&gt;MySQL &amp;gt;= 8.0&lt;/li&gt;
&lt;li&gt;Flutter &amp;gt;= 3.41 (only needed for frontend development)&lt;/li&gt;
&lt;li&gt;Elasticsearch &amp;gt;= 7.x (optional, required for search)&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;Quick-Start&#34;&gt;&lt;a href=&#34;#Quick-Start&#34; class=&#34;headerlink&#34; title=&#34;Quick Start&#34;&gt;&lt;/a&gt;Quick Start&lt;/h2&gt;&lt;h3 id=&#34;1-Install-dependencies&#34;&gt;&lt;a href=&#34;#1-Install-dependencies&#34; class=&#34;headerlink&#34; title=&#34;1. Install dependencies&#34;&gt;&lt;/a&gt;1. Install dependencies&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;composer install&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;2-Configure-environment-variables&#34;&gt;&lt;a href=&#34;#2-Configure-environment-variables&#34; class=&#34;headerlink&#34; title=&#34;2. Configure environment variables&#34;&gt;&lt;/a&gt;2. Configure environment variables&lt;/h3&gt;&lt;p&gt;Copy and edit the environment variables (optional — if you don’t configure them, the defaults in &lt;code&gt;config/*.php&lt;/code&gt; are used):&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.example .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;Key configuration items:&lt;/p&gt;
&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Environment variable&lt;/th&gt;
&lt;th&gt;Description&lt;/th&gt;
&lt;th&gt;Default&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;JWT_SECRET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;JWT signing key&lt;/td&gt;
&lt;td&gt;&lt;code&gt;open-admin-jwt-secret-change-in-production&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;HASHIDS_SALT&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Hashids salt&lt;/td&gt;
&lt;td&gt;&lt;code&gt;open-admin-hashids-salt-2026&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;ENCRYPTION_KEY&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;API encryption key&lt;/td&gt;
&lt;td&gt;32-byte default value&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SNOWFLAKE_DATACENTER_ID&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Datacenter ID (0-31)&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SNOWFLAKE_WORKER_ID&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Worker node ID (0-31)&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SCOUT_HOSTS&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;ES address&lt;/td&gt;
&lt;td&gt;&lt;code&gt;http://localhost:9200&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;In production you must change all keys to random strings.&lt;/strong&gt;&lt;/p&gt;
&lt;h3 id=&#34;3-Initialize-the-database&#34;&gt;&lt;a href=&#34;#3-Initialize-the-database&#34; class=&#34;headerlink&#34; title=&#34;3. Initialize the database&#34;&gt;&lt;/a&gt;3. Initialize the database&lt;/h3&gt;&lt;p&gt;Run the SQL files under &lt;code&gt;database/migrations/&lt;/code&gt; in order:&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Create tables&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root -p &amp;lt; database/migrations/2026_05_16_000000_init_tables.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Seed permission data&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root -p &amp;lt; database/migrations/2026_05_20_000001_seed_permissions.sql&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;4-Start-the-service&#34;&gt;&lt;a href=&#34;#4-Start-the-service&#34; class=&#34;headerlink&#34; title=&#34;4. Start the service&#34;&gt;&lt;/a&gt;4. Start the service&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;php start.php start&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;Listens on &lt;code&gt;http://0.0.0.0:8787&lt;/code&gt; by default.&lt;/p&gt;
&lt;h3 id=&#34;5-Start-the-frontends-optional&#34;&gt;&lt;a href=&#34;#5-Start-the-frontends-optional&#34; class=&#34;headerlink&#34; title=&#34;5. Start the frontends (optional)&#34;&gt;&lt;/a&gt;5. Start the frontends (optional)&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Flutter admin backend (web):&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; apps/flutter&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter pub get&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter run -d chrome    &lt;span class=&#34;comment&#34;&gt;# Web build (PC admin backend style)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;&lt;strong&gt;HarmonyOS client (mobile):&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Open the &lt;code&gt;apps/harmonyos/&lt;/code&gt; directory with DevEco Studio, connect a real device or an emulator and run.&lt;/p&gt;
&lt;h3 id=&#34;6-One-click-Docker-Compose-deployment-recommended-for-production&#34;&gt;&lt;a href=&#34;#6-One-click-Docker-Compose-deployment-recommended-for-production&#34; class=&#34;headerlink&#34; title=&#34;6. One-click Docker Compose deployment (recommended for production)&#34;&gt;&lt;/a&gt;6. One-click Docker Compose deployment (recommended for production)&lt;/h3&gt;&lt;p&gt;The project ships a complete Docker orchestration setup with 5 services: Nginx, PHP (webman app), MySQL, Redis and Elasticsearch.&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 1. Configure the Docker environment variables&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.docker .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 2. Start all services&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker-compose up -d&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 3. Initialize the database (run inside the app container)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker-compose &lt;span class=&#34;built_in&#34;&gt;exec&lt;/span&gt; app mysql -h mysql -u root -p &amp;lt; database/migrations/2026_05_16_000000_init_tables.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker-compose &lt;span class=&#34;built_in&#34;&gt;exec&lt;/span&gt; app mysql -h mysql -u root -p &amp;lt; database/migrations/2026_05_20_000001_seed_permissions.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 4. Access&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# http://localhost:8787  (webman)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# http://localhost:8080  (Nginx reverse proxy)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;Dockerfile&lt;/code&gt;: PHP 8.3 + OPcache + Composer, based on &lt;code&gt;php:8.3-cli&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;docker-compose.yml&lt;/code&gt;: orchestration of 5 services, network isolation, persistent data volumes&lt;/li&gt;
&lt;li&gt;&lt;code&gt;.env.docker&lt;/code&gt;: environment variables dedicated to the Docker environment&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;Database-Conventions&#34;&gt;&lt;a href=&#34;#Database-Conventions&#34; class=&#34;headerlink&#34; title=&#34;Database Conventions&#34;&gt;&lt;/a&gt;Database Conventions&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Table prefix&lt;/strong&gt;: &lt;code&gt;erik_&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Primary key&lt;/strong&gt;: every table’s primary key is &lt;code&gt;id BIGINT UNSIGNED NOT NULL&lt;/code&gt;, with &lt;strong&gt;AUTO_INCREMENT forbidden&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;ID generation&lt;/strong&gt;: primary key IDs are generated by &lt;code&gt;SnowflakeService::generate()&lt;/code&gt; in the application layer, unique across the cluster&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Required fields&lt;/strong&gt;: every table must contain &lt;code&gt;id&lt;/code&gt;, &lt;code&gt;created_at&lt;/code&gt;, &lt;code&gt;updated_at&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Soft delete&lt;/strong&gt;: tables that need soft delete add &lt;code&gt;deleted_at DATETIME DEFAULT NULL&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Sensitive fields&lt;/strong&gt;: phone numbers, emails, ID card numbers and the like are encrypted/decrypted automatically by the &lt;code&gt;encryptable&lt;/code&gt; plugin, with ciphertext stored in &lt;code&gt;VARCHAR(500)&lt;/code&gt; columns&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;API-Conventions&#34;&gt;&lt;a href=&#34;#API-Conventions&#34; class=&#34;headerlink&#34; title=&#34;API Conventions&#34;&gt;&lt;/a&gt;API Conventions&lt;/h2&gt;&lt;h3 id=&#34;API-documentation&#34;&gt;&lt;a href=&#34;#API-documentation&#34; class=&#34;headerlink&#34; title=&#34;API documentation&#34;&gt;&lt;/a&gt;API documentation&lt;/h3&gt;&lt;p&gt;The project uses hg/apidoc to generate API documentation automatically; visit &lt;code&gt;/apidoc&lt;/code&gt; to view it.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Admin APIs: 25 module groups, with complete request parameters and response structures&lt;/li&gt;
&lt;li&gt;Client APIs (Service API): 3 groups — auth/captcha/product&lt;/li&gt;
&lt;li&gt;Every endpoint is annotated with global request headers such as JWT auth, API version and internationalization&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Unified-response-format&#34;&gt;&lt;a href=&#34;#Unified-response-format&#34; class=&#34;headerlink&#34; title=&#34;Unified response format&#34;&gt;&lt;/a&gt;Unified response format&lt;/h3&gt;&lt;figure class=&#34;highlight json&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;code&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;message&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;success&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;data&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Business-error-codes&#34;&gt;&lt;a href=&#34;#Business-error-codes&#34; class=&#34;headerlink&#34; title=&#34;Business error codes&#34;&gt;&lt;/a&gt;Business error codes&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Code&lt;/th&gt;
&lt;th&gt;Meaning&lt;/th&gt;
&lt;th&gt;Notes&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Success&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;400&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Invalid request parameters&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;401&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Not logged in (invalid or expired token)&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;403&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;No permission / security block&lt;/td&gt;
&lt;td&gt;RBAC authorization failure / SecurityFilter attack detection&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;404&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Resource not found&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;422&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Parameter validation failed&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;413&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Request body too large&lt;/td&gt;
&lt;td&gt;Triggered by SecurityFilter, over 10MB&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;405&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Method not allowed&lt;/td&gt;
&lt;td&gt;Triggered by SecurityFilter; only GET/POST/PUT/DELETE/OPTIONS/HEAD are allowed&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;415&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Unsupported media type&lt;/td&gt;
&lt;td&gt;Triggered by SecurityFilter; Content-Type is not JSON&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;429&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Too many requests&lt;/td&gt;
&lt;td&gt;Triggered by RateLimit / account lockout (5 failed logins locks for 15 minutes)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;500&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Internal server error&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Internationalization-1&#34;&gt;&lt;a href=&#34;#Internationalization-1&#34; class=&#34;headerlink&#34; title=&#34;Internationalization&#34;&gt;&lt;/a&gt;Internationalization&lt;/h3&gt;&lt;p&gt;The &lt;code&gt;Accept-Language&lt;/code&gt; request header switches the language automatically (zh-CN → Chinese, en → English); Chinese is the default.&lt;/p&gt;
&lt;h3 id=&#34;ID-handling&#34;&gt;&lt;a href=&#34;#ID-handling&#34; class=&#34;headerlink&#34; title=&#34;ID handling&#34;&gt;&lt;/a&gt;ID handling&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;IDs in requests/responses&lt;/strong&gt;: encrypted with hashids into strings, so real database IDs are never exposed&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;API paths&lt;/strong&gt;: &lt;code&gt;GET /admin/user/&amp;#123;hashid&amp;#125;&lt;/code&gt; — the &lt;code&gt;&amp;#123;id&amp;#125;&lt;/code&gt; in the path is a hashid string&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Database storage&lt;/strong&gt;: the raw BIGINT value, generated by snowflake&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;API-versioning&#34;&gt;&lt;a href=&#34;#API-versioning&#34; class=&#34;headerlink&#34; title=&#34;API versioning&#34;&gt;&lt;/a&gt;API versioning&lt;/h3&gt;&lt;p&gt;The API version is controlled by a request header and is &lt;strong&gt;not part of the URL&lt;/strong&gt;:&lt;/p&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;API-Version&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;v1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;ul&gt;
&lt;li&gt;When no version is provided, &lt;code&gt;v1&lt;/code&gt; is used by default&lt;/li&gt;
&lt;li&gt;Unsupported versions return &lt;code&gt;400 Bad Request&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;To add a version, just create an &lt;code&gt;app/api/&amp;#123;version&amp;#125;/controller/&lt;/code&gt; directory and register the new version in the middleware&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Rate-limiting&#34;&gt;&lt;a href=&#34;#Rate-limiting&#34; class=&#34;headerlink&#34; title=&#34;Rate limiting&#34;&gt;&lt;/a&gt;Rate limiting&lt;/h3&gt;&lt;p&gt;Based on a Redis sliding window algorithm, 60 requests/minute/IP/route by default. Sensitive endpoints are stricter:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Login: 10 requests/minute&lt;/li&gt;
&lt;li&gt;Register: 5 requests/minute&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Responses include the &lt;code&gt;X-RateLimit-Limit&lt;/code&gt;, &lt;code&gt;X-RateLimit-Remaining&lt;/code&gt; and &lt;code&gt;X-RateLimit-Reset&lt;/code&gt; headers. Exceeding the limit returns 429 with a &lt;code&gt;Retry-After&lt;/code&gt; header.&lt;/p&gt;
&lt;h3 id=&#34;Middleware-architecture&#34;&gt;&lt;a href=&#34;#Middleware-architecture&#34; class=&#34;headerlink&#34; title=&#34;Middleware architecture&#34;&gt;&lt;/a&gt;Middleware architecture&lt;/h3&gt;&lt;p&gt;Global middleware applies to every request and runs in order:&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;Locale (automatic Accept-Language detection, sets the locale)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → Cors (CORS preflight + response headers)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → SecurityFilter (HTTP method restriction/request body size/Content-Type validation/XSS/SQL injection/path traversal/command injection/CSRF attack blocking)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → RateLimit (Redis sliding window rate limiting + account lockout: 5 failed logins locks for 15 minutes)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → ApiVersion (API version validation, /api route group)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → AdminAuth (JWT auth + blacklist, /admin route group)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → AdminPermission (RBAC authorization, /admin route group)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → OperationLog (automatic logging for POST/PUT/DELETE, with source client detection, /admin route group)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;&lt;code&gt;/health&lt;/code&gt; and &lt;code&gt;/api/docs&lt;/code&gt; are public endpoints and only pass through &lt;code&gt;Locale → Cors → SecurityFilter → RateLimit&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;Security hardening:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Account lockout&lt;/strong&gt;: after 5 consecutive failed logins the account is locked for 15 minutes, during which login returns 429&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Concurrent session limit&lt;/strong&gt;: a user can have at most 3 valid tokens; beyond that, the oldest token is automatically blacklisted&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;security.txt&lt;/strong&gt;: &lt;code&gt;GET /.well-known/security.txt&lt;/code&gt; provides security contact information per RFC 9116&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Nginx security configuration&lt;/strong&gt;: see &lt;code&gt;docs/nginx-security.conf&lt;/code&gt; for a complete reverse proxy hardening example&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Authentication&#34;&gt;&lt;a href=&#34;#Authentication&#34; class=&#34;headerlink&#34; title=&#34;Authentication&#34;&gt;&lt;/a&gt;Authentication&lt;/h3&gt;&lt;p&gt;Login and registration both require &lt;strong&gt;click captcha&lt;/strong&gt; verification first:&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;The client calls &lt;code&gt;POST /api/captcha/generate&lt;/code&gt; to get the captcha image (base64 PNG) and the list of target words&lt;/li&gt;
&lt;li&gt;The user clicks the positions of the corresponding words in the image in order; the click coordinates are collected as &lt;code&gt;[&amp;#123;x, y&amp;#125;, ...]&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;On login, &lt;code&gt;captcha_key&lt;/code&gt; and &lt;code&gt;clicks&lt;/code&gt; are submitted together; the server verifies the captcha before verifying the credentials&lt;/li&gt;
&lt;/ol&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;POST /api/auth/login&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Content-Type&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;application/json&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;quot;username&amp;quot;: &amp;quot;admin&amp;quot;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;quot;password&amp;quot;: &amp;quot;******&amp;quot;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;quot;captcha_key&amp;quot;: &amp;quot;abc123...&amp;quot;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;quot;clicks&amp;quot;: [&amp;#123;&amp;quot;x&amp;quot;: 120, &amp;quot;y&amp;quot;: 85&amp;#125;, &amp;#123;&amp;quot;x&amp;quot;: 210, &amp;quot;y&amp;quot;: 140&amp;#125;, &amp;#123;&amp;quot;x&amp;quot;: 95, &amp;quot;y&amp;quot;: 170&amp;#125;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;Subsequent admin endpoints require JWT authentication:&lt;/p&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Authorization&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;Bearer &amp;lt;token&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;A successful login returns an access_token valid for 2 hours, plus a refresh_token valid for 14 days.&lt;/p&gt;
&lt;p&gt;On logout the token is added to the Redis blacklist and cannot be reused within its lifetime. POST /admin/profile/logout&lt;/p&gt;
&lt;h3 id=&#34;Secondary-confirmation-for-sensitive-operations&#34;&gt;&lt;a href=&#34;#Secondary-confirmation-for-sensitive-operations&#34; class=&#34;headerlink&#34; title=&#34;Secondary confirmation for sensitive operations&#34;&gt;&lt;/a&gt;Secondary confirmation for sensitive operations&lt;/h3&gt;&lt;p&gt;Sensitive operations such as deleting users, roles or permissions require the current logged-in user’s &lt;code&gt;password&lt;/code&gt; in the request body for a second identity confirmation:&lt;/p&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;DELETE /admin/user/&amp;#123;id&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Content-Type&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;application/json&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Authorization&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;Bearer &amp;lt;token&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123; &amp;quot;password&amp;quot;: &amp;quot;******&amp;quot; &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;API-List&#34;&gt;&lt;a href=&#34;#API-List&#34; class=&#34;headerlink&#34; title=&#34;API List&#34;&gt;&lt;/a&gt;API List&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;All &lt;code&gt;/api/*&lt;/code&gt; endpoints require the &lt;code&gt;API-Version: v1&lt;/code&gt; header (defaults to v1 if omitted).&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;Public-endpoints&#34;&gt;&lt;a href=&#34;#Public-endpoints&#34; class=&#34;headerlink&#34; title=&#34;Public endpoints&#34;&gt;&lt;/a&gt;Public endpoints&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Method&lt;/th&gt;
&lt;th&gt;Path&lt;/th&gt;
&lt;th&gt;Description&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/health&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Health check (DB/Redis/ES status)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/docs&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;OpenAPI 3.0 specification document&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/captcha/generate&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Generate a click captcha&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/captcha/verify&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Verify a click captcha&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/auth/login&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Login (requires captcha)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/auth/register&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Register (requires captcha)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/auth/refresh&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Refresh token&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/metrics&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Prometheus metrics&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Admin-endpoints-JWT-RBAC-required&#34;&gt;&lt;a href=&#34;#Admin-endpoints-JWT-RBAC-required&#34; class=&#34;headerlink&#34; title=&#34;Admin endpoints (JWT + RBAC required)&#34;&gt;&lt;/a&gt;Admin endpoints (JWT + RBAC required)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Method&lt;/th&gt;
&lt;th&gt;Path&lt;/th&gt;
&lt;th&gt;Description&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/dashboard&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Dashboard data (Redis cache for 5 minutes)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
